package com.traceback.core.agent;

import com.fasterxml.jackson.annotation.JsonIgnoreProperties;
import com.traceback.core.agent.tavily.ExternalResearchFinding;
import com.traceback.core.correlation.ConfidenceBreakdown;
import com.traceback.core.domain.Hypothesis;
import com.traceback.core.validation.InvestigationClaim;

import java.time.Instant;
import java.util.Collections;
import java.util.List;
import java.util.UUID;

/**
 * Complete, structured investigation report generated by the autonomous AI Investigation Agent.
 * Grounded in deterministic evidence, validated claims, and external technical research.
 */
@JsonIgnoreProperties(ignoreUnknown = true)
public record InvestigationAgentReport(
        String reportId,
        UUID investigationId,
        String summary,
        String primarySuspectedRootCause,
        List<Hypothesis> alternativeHypotheses,
        List<String> supportingEvidenceIds,
        List<String> contradictoryEvidenceIds,
        ConfidenceBreakdown deterministicConfidenceBreakdown,
        String aiReasoningSummary,
        List<ExternalResearchFinding> externalResearchFindings,
        List<String> sourceUrls,
        List<String> recommendedVerificationSteps,
        List<String> remainingUncertainties,
        AgentInvestigationStatus finalStatus,
        List<InvestigationClaim> validatedClaims,
        List<AgentInvestigationStep> investigationSteps,
        Instant generatedAt
) {
    public InvestigationAgentReport {
        if (alternativeHypotheses == null) alternativeHypotheses = Collections.emptyList();
        if (supportingEvidenceIds == null) supportingEvidenceIds = Collections.emptyList();
        if (contradictoryEvidenceIds == null) contradictoryEvidenceIds = Collections.emptyList();
        if (externalResearchFindings == null) externalResearchFindings = Collections.emptyList();
        if (sourceUrls == null) sourceUrls = Collections.emptyList();
        if (recommendedVerificationSteps == null) recommendedVerificationSteps = Collections.emptyList();
        if (remainingUncertainties == null) remainingUncertainties = Collections.emptyList();
        if (validatedClaims == null) validatedClaims = Collections.emptyList();
        if (investigationSteps == null) investigationSteps = Collections.emptyList();
        if (generatedAt == null) generatedAt = Instant.now();
    }
}
